// 未使用500件の5分割比較で決めた入力条件。NNの重みと探索時間は親から保持する。
// 特徴の順序: M, N, K, floors, wall_fraction, density, mean_per_color, max_color_fraction, color_concentration, rare_fraction, home_mean, home_max, detour_mean, same_nearest_mean, any_nearest_mean, dead_end_fraction, straight4_fraction, stepping2_fraction。最終200件の結果による条件調整はしない。
static array<double,18> nn_selector_features() {
    [[maybe_unused]] const Board &b=board_info;
    int counts[13]{};
    for(int p=0;p<b.cell_count;p++) if(b.initial[p]) counts[b.initial[p]]++;
    const int maximum_color=*max_element(counts+1,counts+b.K+1);
    int squared_counts=0;
    for(int c=1;c<=b.K;c++) squared_counts+=counts[c]*counts[c];
    int rare_slimes=0;
    for(int c=1;c<=b.K;c++) if(counts[c]<=3) rare_slimes+=counts[c];
    int home_sum=0;
    int home_maximum=0;
    double detour_sum=0.;
    for(int p=0;p<b.cell_count;p++) if(b.initial[p]) {
        const int q=b.nest_pos_by_code[b.initial[p]];
        const int distance=b.floor_dist[p][q];
        home_sum+=distance;
        home_maximum=max(home_maximum,distance);
        detour_sum+=double(distance)/(abs(b.row[p]-b.row[q])+abs(b.col[p]-b.col[q]));
    }
    int same_sum=0,same_count=0;
    int any_sum=0;
    for(int p=0;p<b.cell_count;p++) if(b.initial[p]) {
        int same_nearest=infinite_cost;
        int any_nearest=infinite_cost;
        for(int q=0;q<b.cell_count;q++) if(q!=p&&b.initial[q]) {
            if(b.initial[p]==b.initial[q]) same_nearest=min(same_nearest,int(b.floor_dist[p][q]));
            any_nearest=min(any_nearest,int(b.floor_dist[p][q]));
        }
        if(same_nearest<infinite_cost) { same_sum+=same_nearest; same_count++; }
        any_sum+=any_nearest;
    }
    int dead_ends=0;
    for(int p=0;p<b.cell_count;p++) {
        int degree=0; for(int d=0;d<4;d++) degree+=b.adj[p][d]>=0;
        dead_ends+=degree<=1;
    }
    int straight4=0;
    for(int p=0;p<b.cell_count;p++) {
        bool found=false; for(int d=0;d<4;d++) found|=b.ray_count[p][d]>=4;
        straight4+=found;
    }
    int stepping2=0;
    for(int p=0;p<b.cell_count;p++) if(b.initial[p]) {
        bool found=false; for(int d=0;d<4;d++) {
            const int q=b.ray[p][d][2]; if(q>=0&&b.initial[q]) found=true;
        }
        stepping2+=found;
    }
    return {double(b.M), double(b.N), double(b.K), double(b.cell_count), double(1.-double(b.cell_count)/(b.N*b.N)), double(double(b.M)/b.cell_count), double(double(b.M)/b.K), double(double(maximum_color)/b.M), double(double(squared_counts)/(b.M*b.M)), double(double(rare_slimes)/b.M), double(double(home_sum)/b.M), double(home_maximum), double(detour_sum/b.M), double(same_count ? double(same_sum)/same_count : 0.), double(double(any_sum)/b.M), double(double(dead_ends)/b.cell_count), double(double(straight4)/b.cell_count), double(double(stepping2)/b.M)};
}
